import React from "react";
  import MarkDown from "@/components/markdown";
  
  function Index() {
    return <MarkDown srcDoc={"## 简单的数学知识\n\n在实现旋转前，我们先看下面一道题，已知点A(x1, y1)，求点A旋转30度后的点B(x2, y2)\n\n![image](../../easy-webgl/rotate_01.jpg)\n\n\n计算过程如下：\n\n![image](../../easy-webgl/rotate_02.jpg)\n\n\n因此，可以得出下面的公式，其中B就是旋转的弧度。\n\n```js\nx2 = x1 * cosB + y1 * sinB;\ny2 = y1 * cosB - x1 * sinB;\n```\n\n\n## 二维旋转\n基于上面的公式，我们可以很容易求出cosB和sinB\n```js\nvar angleInDegrees = 360 - ui.value;\nvar angleInRadians = (angleInDegrees * Math.PI) / 180;\nrotation[0] = Math.sin(angleInRadians);\nrotation[1] = Math.cos(angleInRadians);\n```\n\n然后在顶点着色器中，将计算后的值传给顶点着色器。\n\n```js\nvec2 rotatedPosition = vec2(a_position.x * u_rotation.y + a_position.y * u_rotation.x, a_position.y * u_rotation.y - a_position.x * u_rotation.x);\n\n```\n\n结果如下：\n\n![image](../../easy-webgl/rotate_03.jpg)\n\n\n## 完整代码\n完整代码如下：\n\n```html\n<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <meta name=\"theme-color\" content=\"#000000\" />\n    <meta name=\"description\" content=\"WebGL\" />\n    <title>WebGL</title>\n    <style>\n      @import url(\"./webgl-tutorials.css\");\n\n      body {\n        margin: 20px;\n      }\n\n      #webgl {\n        width: 500px;\n        height: 500px;\n      }\n\n      .container {\n        font-size: 0;\n        display: inline-block;\n        /* border: 1px solid black; */\n      }\n\n      #ui {\n        width: 200px;\n      }\n    </style>\n  </head>\n\n  <body>\n    <div id=\"uiContainer\">\n      <div id=\"ui\">\n        <div id=\"x\"></div>\n        <div id=\"y\"></div>\n        <div id=\"angle\"></div>\n      </div>\n    </div>\n    <div class=\"container\">\n      <canvas width=\"500\" height=\"500\" id=\"webgl\"\n        >你的浏览器不支持canvas</canvas\n      >\n    </div>\n    <script src=\"./webgl-lessons-ui.js\"></script>\n\n    <script src=\"./initShaders.js\"></script>\n    <script>\n      const main = (image) => {\n        const canvas = document.getElementById(\"webgl\");\n\n        const gl = canvas.getContext(\"webgl\");\n        const vertexShaderSource1 = `\n        attribute vec2 a_position;\n        uniform vec2 u_translation;\n        uniform vec2 u_rotation;\n        void main(){\n            gl_PointSize = 10.0;\n            vec2 rotatedPosition = vec2(a_position.x * u_rotation.y + a_position.y * u_rotation.x, a_position.y * u_rotation.y - a_position.x * u_rotation.x);\n            vec2 position = rotatedPosition + u_translation;\n            gl_Position = vec4(position, 0.0, 1.0);\n        }\n      `;\n        const fragmentShaderSource1 = `\n        precision mediump float;\n        void main(){\n          gl_FragColor = vec4(1.0, 0.0, 0.0, 1.0);\n        }\n      `;\n        const program1 = initShaders(\n          gl,\n          vertexShaderSource1,\n          fragmentShaderSource1\n        );\n        const positionLocation1 = gl.getAttribLocation(program1, \"a_position\");\n        const translationLocation = gl.getUniformLocation(\n          program1,\n          \"u_translation\"\n        );\n        const rotationLocation = gl.getUniformLocation(program1, \"u_rotation\");\n        const rectX = 0,\n          rectY =0,\n          rectWidth = 0.5,\n          rectHeight = 0.8,\n          thickness = 0.1;\n        let verticesInfo = [\n          // 左竖\n          rectX,\n          rectY,\n          rectX + thickness,\n          rectY,\n          rectX,\n          rectY - rectHeight,\n          rectX,\n          rectY - rectHeight,\n          rectX + thickness,\n          rectY,\n          rectX + thickness,\n          rectY - rectHeight,\n          // 上横\n          rectX + thickness,\n          rectY,\n          rectX + thickness,\n          rectY - thickness,\n          rectX + rectWidth,\n          rectY,\n          rectX + rectWidth,\n          rectY,\n          rectX + rectWidth,\n          rectY - thickness,\n          rectX + thickness,\n          rectY - thickness,\n          // 中横\n          rectX + thickness,\n          rectY - 0.3,\n          rectX + thickness,\n          rectY - 0.3 - thickness,\n          rectX + rectWidth - 0.1,\n          rectY - 0.3,\n          rectX + rectWidth - 0.1,\n          rectY - 0.3,\n          rectX + thickness,\n          rectY - 0.3 - thickness,\n          rectX + rectWidth - 0.1,\n          rectY - 0.3 - thickness,\n        ];\n\n        verticesInfo = new Float32Array(verticesInfo);\n\n        const vertexBuffer = gl.createBuffer();\n        gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);\n        gl.bufferData(gl.ARRAY_BUFFER, verticesInfo, gl.STATIC_DRAW);\n\n        gl.vertexAttribPointer(positionLocation1, 2, gl.FLOAT, false, 8, 0);\n\n        gl.enableVertexAttribArray(positionLocation1);\n\n        gl.clearColor(0, 0, 0, 0);\n\n        gl.clear(gl.COLOR_BUFFER_BIT);\n\n        gl.useProgram(program1);\n\n        var translation = [0, 0];\n        var rotation = [0, 1];\n        gl.uniform2fv(rotationLocation, rotation);\n        gl.uniform2fv(translationLocation, translation);\n\n        function updatePosition(index) {\n          return function (event, ui) {\n            const v =\n              (index === 0\n                ? ui.value / (gl.canvas.width + 5)\n                : -ui.value / (gl.canvas.height + 5)) * 2;\n            translation[index] = v;\n            gl.uniform2fv(translationLocation, translation);\n            gl.drawArrays(gl.TRIANGLES, 0, 18);\n          };\n        }\n        function updateAngle(event, ui) {\n          var angleInDegrees = 360 - ui.value;\n          var angleInRadians = (angleInDegrees * Math.PI) / 180;\n          rotation[0] = Math.sin(angleInRadians);\n          rotation[1] = Math.cos(angleInRadians);\n          gl.uniform2fv(rotationLocation, rotation);\n          gl.drawArrays(gl.TRIANGLES, 0, 18);\n        }\n        webglLessonsUI.setupSlider(\"#x\", {\n          slide: updatePosition(0),\n          max: gl.canvas.width,\n        });\n        webglLessonsUI.setupSlider(\"#y\", {\n          slide: updatePosition(1),\n          max: gl.canvas.height,\n        });\n        webglLessonsUI.setupSlider(\"#angle\", { slide: updateAngle, max: 360 });\n\n        gl.drawArrays(gl.TRIANGLES, 0, 18);\n      };\n\n      main();\n    </script>\n  </body>\n</html>\n\n```"} />;
  }
  
  export default Index;